mapper.select:
SELECT
    id AS couple_id,
    profile_message
FROM couple
WHERE inviter_id = #{memberId}
   OR invitee_id = #{memberId}

mapper.update:
UPDATE couple
SET profile_message = #{profileMessage}
WHERE inviter_id = #{memberId}
   OR invitee_id = #{memberId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM couple
    WHERE inviter_id = #{memberId}
       OR invitee_id = #{memberId}
)

mapper.insert:
